import React, { useContext } from 'react';
import { SafeAreaView, ScrollView, Text, TouchableOpacity, View } from 'react-native';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { DetritosContext } from '../context/DetritosContext';
import Header from '../components/Header';
import MetricCard from '../components/MetricCard';
import { colors } from '../styles/theme';
import styles from '../styles/screens/HomeScreenStyles';

const HomeScreen = ({ navigation }) => {
  const { metrics, alertas, detritos } = useContext(DetritosContext);

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
        <Header
          title="NeoHorizon"
          subtitle="Segurança orbital, monitoramento de detritos e sustentabilidade espacial em um só lugar"
        />

        <View style={styles.metricsRow}>
          <MetricCard label="Detritos monitorados" value={metrics.totalDetritos.toString()} accent={colors.primary} />
          <MetricCard label="Alertas ativos" value={metrics.totalAlertas.toString()} accent={colors.secondary} />
        </View>

        <View style={styles.cardLarge}>
          <Text style={styles.sectionTitle}>Próxima aproximação de risco</Text>
          <Text style={styles.sectionValue}>{metrics.proximidadeRisco}</Text>
          <Text style={styles.sectionDescription}>Avaliação da janela orbital e recomendações para prevenção de colisões.</Text>
        </View>

        <View style={styles.buttonRow}>
          <TouchableOpacity style={styles.actionButton} onPress={() => navigation.navigate('Detritos')}>
            <MaterialCommunityIcons name="satellite" size={20} color={colors.text} />
            <Text style={styles.actionText}>Ver detritos</Text>
          </TouchableOpacity>
          <TouchableOpacity style={[styles.actionButton, styles.actionButtonSecondary]} onPress={() => navigation.navigate('CadastroDetrito')}>
            <MaterialCommunityIcons name="plus-circle" size={20} color={colors.text} />
            <Text style={styles.actionText}>Novo registro</Text>
          </TouchableOpacity>
        </View>

        <View style={styles.statusCard}>
          <Text style={styles.sectionTitle}>Indicadores orbitais</Text>
          {Object.entries(metrics.porRegiao).map(([regiao, total]) => (
            <View style={styles.statusRow} key={regiao}>
              <Text style={styles.statusLabel}>{regiao}</Text>
              <Text style={styles.statusValue}>{total} detritos</Text>
            </View>
          ))}
        </View>

        <View style={styles.alertCard}>
          <Text style={styles.sectionTitle}>Alertas críticos</Text>
          {alertas.length ? (
            alertas.slice(0, 3).map((alerta) => (
              <View key={alerta.id} style={styles.alertRow}>
                <Text style={styles.alertName}>{alerta.nome}</Text>
                <Text style={styles.alertBadge}>{alerta.nivel}</Text>
              </View>
            ))
          ) : (
            <Text style={styles.sectionDescription}>Nenhum alerta crítico encontrado. A órbita estável.</Text>
          )}
        </View>

        <TouchableOpacity style={styles.linkButton} onPress={() => navigation.navigate('Alertas')}>
          <Text style={styles.linkText}>Ver todos os alertas críticos</Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
};

export default HomeScreen;
